 1 | /**
 2 |  * Channel Consistency Check Module
 3 |  * 
 4 |  * Independent verification layer comparing STRUCTURAL redaction (dom_summary.elements)
 5 |  * with VISUAL redaction (redactedRegions) before network dispatch.
 6 |  */
 7 | 
 8 | /**
 9 |  * Checks whether structural redaction requirements match actual visual redaction regions.
10 |  *
11 |  * @param {object} payload - Payload containing dom_summary.elements
12 |  * @param {Array<{element_id: string, bounding_box: object}>} redactedRegions - Regions visually redacted
13 |  * @returns {{ consistent: boolean, mismatches: Array<{element_id: string, issue: string}> }}
14 |  */
15 | export function checkChannelConsistency(payload, redactedRegions) {
16 |   const mismatches = [];
17 | 
18 |   const elements = (payload && payload.dom_summary && Array.isArray(payload.dom_summary.elements))
19 |     ? payload.dom_summary.elements
20 |     : [];
21 | 
22 |   const regions = Array.isArray(redactedRegions) ? redactedRegions : [];
23 | 
24 |   // 1. Set of element_ids that SHOULD be redacted
25 |   const shouldBeRedacted = new Set();
26 |   for (const el of elements) {
27 |     if (el && el.is_sensitive === true && el.semantic_token !== null) {
28 |       if (el.element_id) {
29 |         shouldBeRedacted.add(el.element_id);
30 |       }
31 |     }
32 |   }
33 | 
34 |   // 2. Set of element_ids that WERE ACTUALLY visually redacted
35 |   const actuallyRedacted = new Set();
36 |   for (const region of regions) {
37 |     if (region && region.element_id) {
38 |       actuallyRedacted.add(region.element_id);
39 |     }
40 |   }
41 | 
42 |   // 3. Compare sets
43 |   // Structural claimed but visual missing
44 |   for (const id of shouldBeRedacted) {
45 |     if (!actuallyRedacted.has(id)) {
46 |       mismatches.push({
47 |         element_id: id,
48 |         issue: 'structural redaction claimed but visual redaction missing'
49 |       });
50 |     }
51 |   }
52 | 
53 |   // Visual present but structural missing/not sensitive
54 |   for (const id of actuallyRedacted) {
55 |     if (!shouldBeRedacted.has(id)) {
56 |       mismatches.push({
57 |         element_id: id,
58 |         issue: 'visual redaction present but structural summary shows no sensitivity — possible over-redaction or stale data'
59 |       });
60 |     }
61 |   }
62 | 
63 |   // 4. Consistent if no mismatches
64 |   return {
65 |     consistent: mismatches.length === 0,
66 |     mismatches
67 |   };
68 | }
69 | 
70 | /**
71 |  * Hard gate that throws a descriptive Error if visual and structural redactions do not agree.
72 |  *
73 |  * @param {object} payload - Payload containing dom_summary.elements
74 |  * @param {Array<{element_id: string, bounding_box: object}>} redactedRegions - Regions visually redacted
75 |  * @throws {Error} If channel consistency check fails
76 |  */
77 | export function assertChannelsConsistent(payload, redactedRegions) {
78 |   const result = checkChannelConsistency(payload, redactedRegions);
79 | 
80 |   if (!result.consistent) {
81 |     const details = result.mismatches
82 |       .map(m => `  - [${m.element_id}]: ${m.issue}`)
83 |       .join('\n');
84 | 
85 |     throw new Error(
86 |       `Channel consistency check failed with ${result.mismatches.length} mismatch(es):\n${details}`
87 |     );
88 |   }
89 | }

