  1 | /**
  2 |  * Helper to resolve nearby label text for a given DOM element.
  3 |  * Checks in order: associated <label for=id> or parent <label>, aria-label, placeholder,
  4 |  * and closest preceding sibling text node within the same parent.
  5 |  * @param {HTMLElement} el
  6 |  * @returns {string|null}
  7 |  */
  8 | function getNearbyLabelText(el) {
  9 |   if (!el || typeof el.getAttribute !== 'function') {
 10 |     return null;
 11 |   }
 12 | 
 13 |   if (el.labels && el.labels.length > 0) {
 14 |     for (let i = 0; i < el.labels.length; i++) {
 15 |       const text = (el.labels[i].textContent || '').trim();
 16 |       if (text) return text;
 17 |     }
 18 |   }
 19 | 
 20 |   if (el.id && el.ownerDocument && typeof el.ownerDocument.querySelector === 'function') {
 21 |     try {
 22 |       const escapeId = typeof CSS !== 'undefined' && CSS.escape ? CSS.escape(el.id) : el.id;
 23 |       const labelEl = el.ownerDocument.querySelector(`label[for="${escapeId}"]`);
 24 |       if (labelEl) {
 25 |         const text = (labelEl.textContent || '').trim();
 26 |         if (text) return text;
 27 |       }
 28 |     } catch (e) {
 29 |       // Fallback if querySelector fails
 30 |     }
 31 |   }
 32 | 
 33 |   if (typeof el.closest === 'function') {
 34 |     const parentLabel = el.closest('label');
 35 |     if (parentLabel) {
 36 |       const text = (parentLabel.textContent || '').trim();
 37 |       if (text) return text;
 38 |     }
 39 |   }
 40 | 
 41 |   const ariaLabel = el.getAttribute('aria-label');
 42 |   if (ariaLabel && ariaLabel.trim()) {
 43 |     return ariaLabel.trim();
 44 |   }
 45 | 
 46 |   const placeholder = el.getAttribute('placeholder');
 47 |   if (placeholder && placeholder.trim()) {
 48 |     return placeholder.trim();
 49 |   }
 50 | 
 51 |   let curr = el.previousSibling;
 52 |   while (curr) {
 53 |     const text = (curr.textContent || '').trim();
 54 |     if (text) {
 55 |       return text;
 56 |     }
 57 |     curr = curr.previousSibling;
 58 |   }
 59 | 
 60 |   return null;
 61 | }
 62 | 
 63 | /**
 64 |  * Classifies a DOM element based on form heuristics and sensitivity rules.
 65 |  * Order of evaluation: PASSWORD -> CARD_NUMBER -> EMAIL -> AMOUNT -> PHONE -> NAME -> UNKNOWN
 66 |  * @param {HTMLElement} el
 67 |  * @returns {{ tag: string, role: string|null, label_text: string|null, is_sensitive: boolean, sensitivity_type: "PASSWORD"|"CARD_NUMBER"|"EMAIL"|"PHONE"|"NAME"|"AMOUNT"|"UNKNOWN"|null }}
 68 |  */
 69 | export function classifyElement(el) {
 70 |   if (!el || typeof el.getAttribute !== 'function') {
 71 |     return {
 72 |       tag: '',
 73 |       role: null,
 74 |       label_text: null,
 75 |       is_sensitive: false,
 76 |       sensitivity_type: 'UNKNOWN'
 77 |     };
 78 |   }
 79 | 
 80 |   const tag = el.tagName ? el.tagName.toLowerCase() : '';
 81 |   const role = el.getAttribute('role') || null;
 82 |   const typeAttr = (el.getAttribute('type') || '').toLowerCase();
 83 |   const autocompleteAttr = (el.getAttribute('autocomplete') || '').toLowerCase();
 84 |   const placeholderAttr = (el.getAttribute('placeholder') || '').toLowerCase();
 85 | 
 86 |   // Hard exclusion for buttons
 87 |   if (tag === 'button' || typeAttr === 'submit' || typeAttr === 'button' || role === 'button') {
 88 |     return {
 89 |       tag: 'button',
 90 |       role: 'button',
 91 |       label_text: el.innerText || el.textContent || null,
 92 |       is_sensitive: false,
 93 |       sensitivity_type: null
 94 |     };
 95 |   }
 96 | 
 97 |   const label_text = getNearbyLabelText(el);
 98 |   const elText = (el.innerText || el.textContent || '').trim();
 99 | 
100 |   // 1. Password
101 |   if (typeAttr === 'password') {
102 |     return {
103 |       tag,
104 |       role,
105 |       label_text,
106 |       is_sensitive: true,
107 |       sensitivity_type: 'PASSWORD'
108 |     };
109 |   }
110 | 
111 |   // 2. Card Number
112 |   if (autocompleteAttr.includes('cc-number')) {
113 |     return {
114 |       tag,
115 |       role,
116 |       label_text,
117 |       is_sensitive: true,
118 |       sensitivity_type: 'CARD_NUMBER'
119 |     };
120 |   }
121 | 
122 |   // 3. Email
123 |   if (autocompleteAttr.includes('email') || typeAttr === 'email') {
124 |     return {
125 |       tag,
126 |       role,
127 |       label_text,
128 |       is_sensitive: true,
129 |       sensitivity_type: 'EMAIL'
130 |     };
131 |   }
132 | 
133 |   // 4. Amount (Checked BEFORE Phone to prioritize price/total displays over ambiguous nearby sibling text)
134 |   if (
135 |     (label_text && /amount|price|total/i.test(label_text)) ||
136 |     (placeholderAttr && /amount|price|total/i.test(placeholderAttr)) ||
137 |     (elText && /amount|price|total|\$\d/i.test(elText))
138 |   ) {
139 |     return {
140 |       tag,
141 |       role,
142 |       label_text: label_text || (elText || null),
143 |       is_sensitive: true,
144 |       sensitivity_type: 'AMOUNT'
145 |     };
146 |   }
147 | 
148 |   // 5. Phone
149 |   if (
150 |     autocompleteAttr.includes('tel') ||
151 |     typeAttr === 'tel' ||
152 |     (label_text && /phone|mobile|contact number/i.test(label_text)) ||
153 |     (placeholderAttr && /phone|mobile|contact number/i.test(placeholderAttr))
154 |   ) {
155 |     return {
156 |       tag,
157 |       role,
158 |       label_text,
159 |       is_sensitive: true,
160 |       sensitivity_type: 'PHONE'
161 |     };
162 |   }
163 | 
164 |   // 6. Name
165 |   if (autocompleteAttr.includes('name') || (label_text && /name/i.test(label_text))) {
166 |     return {
167 |       tag,
168 |       role,
169 |       label_text,
170 |       is_sensitive: true,
171 |       sensitivity_type: 'NAME'
172 |     };
173 |   }
174 | 
175 |   return {
176 |     tag,
177 |     role,
178 |     label_text,
179 |     is_sensitive: false,
180 |     sensitivity_type: 'UNKNOWN'
181 |   };
182 | }
183 | 
184 | let elementIdCounter = 0;
185 | 
186 | /**
187 |  * Generates a stable selector-like ID for an element.
188 |  * @param {HTMLElement} el
189 |  * @returns {string}
190 |  */
191 | export function getElementId(el) {
192 |   if (!el || typeof el.getAttribute !== 'function') {
193 |     return '';
194 |   }
195 | 
196 |   if (el.id && el.id.trim() !== '') {
197 |     return el.id;
198 |   }
199 | 
200 |   if (typeof el.hasAttribute === 'function' && el.hasAttribute('data-ext-id')) {
201 |     return el.getAttribute('data-ext-id');
202 |   }
203 | 
204 |   const generatedId = `ext-el-${Date.now()}-${++elementIdCounter}`;
205 |   if (typeof el.setAttribute === 'function') {
206 |     el.setAttribute('data-ext-id', generatedId);
207 |   }
208 |   return generatedId;
209 | }

