  1 | const SEMANTIC_TOKEN_PATTERN = /^\[[A-Z0-9_]+(?:\?|: [^\]]+)?\]$/;
  2 | const SENSITIVE_KEY_PATTERN = /password|pwd|secret|credit_card|cvv|ssn|aadhaar|otp/i;
  3 | 
  4 | /**
  5 |  * Recursively walks an object tree and invokes a callback for every string value found.
  6 |  * @param {*} node - Current node in the object tree.
  7 |  * @param {string} path - Dot-notation path to the current node.
  8 |  * @param {function} callback - Called with (stringValue, path) for each string leaf.
  9 |  * @param {Set} seen - Tracks visited references to avoid circular loops.
 10 |  */
 11 | function walkStrings(node, path, callback, seen) {
 12 |   if (node === null || node === undefined) return;
 13 | 
 14 |   if (seen.has(node)) return;
 15 | 
 16 |   if (typeof node === 'string') {
 17 |     callback(node, path);
 18 |     return;
 19 |   }
 20 | 
 21 |   if (typeof node !== 'object') return;
 22 | 
 23 |   seen.add(node);
 24 | 
 25 |   if (Array.isArray(node)) {
 26 |     for (let i = 0; i < node.length; i++) {
 27 |       walkStrings(node[i], path + '[' + i + ']', callback, seen);
 28 |     }
 29 |     return;
 30 |   }
 31 | 
 32 |   const keys = Object.keys(node);
 33 |   for (const key of keys) {
 34 |     const childPath = path ? path + '.' + key : key;
 35 |     walkStrings(node[key], childPath, callback, seen);
 36 |   }
 37 | }
 38 | 
 39 | /**
 40 |  * Scans an outgoing payload for any raw PII values or sensitive text that leaked through redaction.
 41 |  * @param {object} payload - The full payload object to audit.
 42 |  * @param {function} piiDetectFn - PII detection function with signature (text: string) => Array<{type: string, match: string}>
 43 |  * @returns {{ passed: boolean, violations: Array<{path: string, reason: string, matched_type: string}> }}
 44 |  */
 45 | export function auditPayload(payload, piiDetectFn) {
 46 |   const violations = [];
 47 | 
 48 |   if (!payload || typeof payload !== 'object') {
 49 |     return { passed: true, violations };
 50 |   }
 51 | 
 52 |   if (typeof piiDetectFn !== 'function') {
 53 |     return { passed: true, violations };
 54 |   }
 55 | 
 56 |   const seen = new Set();
 57 | 
 58 |   walkStrings(payload, '', function onString(value, path) {
 59 |     // Skip redacted_image_base64 — it's expected binary/opaque data.
 60 |     // But flag a warning if it looks suspiciously short or malformed.
 61 |     if (path === 'redacted_image_base64') {
 62 |       if (typeof value === 'string' && value.length < 100) {
 63 |         violations.push({
 64 |           path,
 65 |           reason: 'redacted_image_base64 is suspiciously short or malformed',
 66 |           matched_type: 'IMAGE_DATA_WARNING'
 67 |         });
 68 |       }
 69 |       return;
 70 |     }
 71 | 
 72 |     // Skip values that are semantic token placeholders
 73 |     if (SEMANTIC_TOKEN_PATTERN.test(value)) {
 74 |       return;
 75 |     }
 76 | 
 77 |     // 1. Check PII detection regex matches
 78 |     const matches = piiDetectFn(value);
 79 |     if (Array.isArray(matches) && matches.length > 0) {
 80 |       for (const match of matches) {
 81 |         violations.push({
 82 |           path,
 83 |           reason: 'raw PII value found outside semantic token',
 84 |           matched_type: match.type || 'UNKNOWN'
 85 |         });
 86 |       }
 87 |     }
 88 | 
 89 |     // 2. Check for unredacted passwords or secrets in sensitive fields/keys
 90 |     if (SENSITIVE_KEY_PATTERN.test(path) && value && !SEMANTIC_TOKEN_PATTERN.test(value)) {
 91 |       violations.push({
 92 |         path,
 93 |         reason: 'unredacted password or secret string found in sensitive field',
 94 |         matched_type: 'PASSWORD'
 95 |       });
 96 |     }
 97 |   }, seen);
 98 | 
 99 |   return {
100 |     passed: violations.length === 0,
101 |     violations
102 |   };
103 | }
104 | 
105 | /**
106 |  * Hard gate that throws a descriptive Error if the payload contains leaked PII.
107 |  * Intended to be called immediately before any fetch() call in the transport module.
108 |  * @param {object} payload - The full payload object to audit.
109 |  * @param {function} piiDetectFn - PII detection function.
110 |  * @throws {Error} If any PII violations are detected.
111 |  */
112 | export function assertSafeToSend(payload, piiDetectFn) {
113 |   const result = auditPayload(payload, piiDetectFn);
114 | 
115 |   if (!result.passed) {
116 |     const details = result.violations
117 |       .map(function (v) {
118 |         return '  - [' + v.matched_type + '] at "' + v.path + '": ' + v.reason;
119 |       })
120 |       .join('\n');
121 | 
122 |     throw new Error(
123 |       'Payload safety audit failed with ' + result.violations.length +
124 |       ' violation(s). Blocking network request.\n' + details
125 |     );
126 |   }
127 | }
128 | 
129 | /**
130 |  * Higher-order transport wrapper enforcing fail-closed security.
131 |  * Guarantees assertSafeToSend runs on the final payload immediately before transportFn is called.
132 |  * If audit fails, transportFn is ZERO-invoked and an Error is thrown.
133 |  *
134 |  * @param {function} transportFn - Network send function with signature (payload) => Promise<any> | any
135 |  * @param {function} piiDetectFn - PII detection function
136 |  * @returns {function(object): Promise<any> | any} Wrapped transport function
137 |  */
138 | export function createSecureTransport(transportFn, piiDetectFn) {
139 |   if (typeof transportFn !== 'function') {
140 |     throw new Error('createSecureTransport requires a valid transport function.');
141 |   }
142 | 
143 |   return function sendSecurePayload(payload) {
144 |     // Hard gate assertion on the FINAL assembled payload immediately before transport
145 |     assertSafeToSend(payload, piiDetectFn);
146 |     return transportFn(payload);
147 |   };
148 | }

