 1 | /**
 2 |  * Detects Personally Identifiable Information (PII) in a given text.
 3 |  * @param {string} text - The input string to analyze.
 4 |  * @returns {Array<{type: string, match: string, startIndex: number, endIndex: number}>}
 5 |  */
 6 | export function detectPII(text) {
 7 |   if (typeof text !== 'string' || !text) {
 8 |     return [];
 9 |   }
10 | 
11 |   const results = [];
12 | 
13 |   const patterns = [
14 |     { type: 'EMAIL', regex: /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g },
15 |     { type: 'PHONE', regex: /(?<!\d)[6-9]\d{9}(?!\d)/g },
16 |     { type: 'CARD_NUMBER', regex: /(?<!\d[ -]?)(?:\d[ -]?){15}\d(?![ -]?\d)/g },
17 |     { type: 'AADHAAR', regex: /(?<!\d[ -]?)(?:\d[ -]?){11}\d(?![ -]?\d)/g },
18 |     { type: 'IFSC', regex: /\b[A-Za-z]{4}0[A-Za-z0-9]{6}\b/g }
19 |   ];
20 | 
21 |   for (const { type, regex } of patterns) {
22 |     let match;
23 |     regex.lastIndex = 0;
24 |     while ((match = regex.exec(text)) !== null) {
25 |       results.push({
26 |         type,
27 |         match: match[0],
28 |         startIndex: match.index,
29 |         endIndex: match.index + match[0].length
30 |       });
31 |     }
32 |   }
33 | 
34 |   const otpRegex = /(?<!\d[ -]?)\d{4,6}(?![ -]?\d)/g;
35 |   const otpContextRegex = /\b(otp|code|verification)\b/i;
36 |   let match;
37 | 
38 |   while ((match = otpRegex.exec(text)) !== null) {
39 |     const startIndex = match.index;
40 |     const endIndex = startIndex + match[0].length;
41 | 
42 |     const contextStart = Math.max(0, startIndex - 30);
43 |     const contextEnd = Math.min(text.length, endIndex + 30);
44 |     const context = text.substring(contextStart, contextEnd);
45 | 
46 |     if (otpContextRegex.test(context)) {
47 |       results.push({
48 |         type: 'OTP',
49 |         match: match[0],
50 |         startIndex,
51 |         endIndex
52 |       });
53 |     }
54 |   }
55 | 
56 |   return results;
57 | }

