 32 | export function processPageForRedaction(elements = [], sourceCanvasOrImage, tokenVault) {
 33 |   const currentUrl = typeof window !== 'undefined' && window.location ? window.location.href : '';
 34 | 
 35 |   const summaryElements = [];
 36 |   const confidenceNotes = [];
 37 |   const sensitiveRegions = [];
 38 |   const sensitiveRawValues = [];
 39 |   const redactedRegionsList = [];
