 43 |       if (!el) continue;
 44 | 
 45 |       const element_id = getElementId(el);
 46 |       const elementClassification = classifyElement(el);
 47 | 
 48 |       const rect = typeof el.getBoundingClientRect === 'function'
 49 |         ? el.getBoundingClientRect()
 50 |         : { x: 0, y: 0, left: 0, top: 0, width: 0, height: 0 };
 51 | 
 52 |       const bounding_box = {
 53 |         x: Math.round(rect.x || rect.left || 0),
 54 |         y: Math.round(rect.y || rect.top || 0),
 55 |         w: Math.round(rect.width || 0),
 56 |         h: Math.round(rect.height || 0)
 57 |       };
 58 | 
 59 |       // 1. Extract rawValue by priority order
 60 |       let rawValue = null;
 61 |       if (el.value !== undefined && el.value !== null && String(el.value).trim() !== '') {
 62 |         rawValue = el.value;
 63 |       } else if (el.innerText && el.innerText.trim() !== '') {
 64 |         rawValue = el.innerText.trim();
 65 |       } else {
 66 |         rawValue = null;
 67 |       }
 68 | 
 69 |       const textToScan = rawValue || el.textContent || '';
 70 |       const piiMatches = detectPII(textToScan);
 71 | 
 72 |       // 2. Classify sensitivity passing rawValue and tokenVault
 73 |       const sensitivity = classifySensitivity(elementClassification, piiMatches, rawValue, tokenVault);
 74 |       const { sensitivity_tier, sensitivity_type, semantic_token } = sensitivity;
 75 |       const is_sensitive = sensitivity_tier !== 3;
 76 | 
 77 |       // 3. Verify token presence in vault
 78 |       const has_stable_token = Boolean(
 79 |         semantic_token &&
 80 |         tokenVault &&
 81 |         typeof tokenVault.hasToken === 'function' &&
 82 |         tokenVault.hasToken(semantic_token)
 83 |       );
 84 | 
 85 |       summaryElements.push({
 86 |         element_id,
 87 |         tag: elementClassification.tag,
 88 |         role: elementClassification.role,
 89 |         label_text: elementClassification.label_text,
