 91 |         sensitivity_tier,
 92 |         sensitivity_type,
 93 |         semantic_token,
 94 |         has_stable_token,
 95 |         bounding_box
 96 |       });
 97 | 
 98 |       let confidence = 0.92;
 99 |       let method = 'dom_heuristic';
100 | 
101 |       if (elementClassification && elementClassification.sensitivity_type !== 'UNKNOWN') {
102 |         confidence = 0.92;
103 |         method = 'dom_heuristic';
104 |       } else if (piiMatches && piiMatches.length > 0) {
105 |         confidence = 0.6;
106 |         method = 'ocr_regex';
107 |       }
108 | 
109 |       confidenceNotes.push({
110 |         element_id,
111 |         confidence,
112 |         method
113 |       });
114 | 
115 |       if (sensitivity_tier === 1 || sensitivity_tier === 2) {
116 |         sensitiveRegions.push({
117 |           bounding_box,
118 |           sensitivity_tier
119 |         });
120 | 
121 |         redactedRegionsList.push({
122 |           element_id,
123 |           bounding_box,
124 |           sensitivity_tier,
125 |           semantic_token
126 |         });
127 | 
128 |         if (rawValue && String(rawValue).trim()) {
129 |           sensitiveRawValues.push(String(rawValue).trim());
130 |         }
131 |         for (const m of piiMatches) {
132 |           if (m && m.match && m.match.trim()) {
133 |             sensitiveRawValues.push(m.match.trim());
134 |           }
135 |         }
136 |       }
137 |     }
138 |   }
139 | 
140 |   const redactedCanvas = redactImage(sourceCanvasOrImage, sensitiveRegions);
141 |   const redacted_image_base64 = canvasToBase64(redactedCanvas);
142 | 
