150 |     redacted_regions: redactedRegionsList
151 |   };
152 | 
153 |   // Top-level Recursive Guard Assertion: confirm no sensitive raw values leak into output object tree
154 |   function walkAndAssert(node, path) {
155 |     if (node === null || node === undefined) return;
156 |     if (path === 'redacted_image_base64') return;
157 | 
158 |     if (typeof node === 'string') {
159 |       for (const rawVal of sensitiveRawValues) {
160 |         if (!rawVal || rawVal.length < 3) continue;
161 |         if (node.includes(rawVal) && !node.startsWith('[')) {
162 |           throw new Error(`Privacy Assertion Violated: Raw sensitive value "${rawVal}" found in output object at "${path}"`);
163 |         }
164 |       }
