166 |     }
167 | 
168 |     if (typeof node !== 'object') return;
169 | 
170 |     if (Array.isArray(node)) {
171 |       for (let i = 0; i < node.length; i++) {
172 |         walkAndAssert(node[i], `${path}[${i}]`);
173 |       }
174 |       return;
175 |     }
176 | 
177 |     for (const key of Object.keys(node)) {
178 |       const childPath = path ? `${path}.${key}` : key;
179 |       walkAndAssert(node[key], childPath);
180 |     }
181 |   }
182 | 
183 |   walkAndAssert(output, '');
184 | 
185 |   return output;
