 23 |   const width = sourceCanvasOrImage.width || sourceCanvasOrImage.naturalWidth || 0;
 24 |   const height = sourceCanvasOrImage.height || sourceCanvasOrImage.naturalHeight || 0;
 25 | 
 26 |   let outputCanvas;
