 28 |     outputCanvas = document.createElement('canvas');
 29 |     outputCanvas.width = width;
 30 |     outputCanvas.height = height;
 31 |   } else {
 32 |     // Environment fallback (e.g. Node test runner without DOM)
 33 |     outputCanvas = {
 34 |       width,
 35 |       height,
 36 |       getContext: () => ({
 37 |         drawImage: () => {},
 38 |         fillRect: () => {},
 39 |         clearRect: () => {},
 40 |         getImageData: () => ({ data: new Uint8ClampedArray(4) })
 41 |       }),
