 54 | 
 55 |       const tier = region.sensitivity_tier;
 56 |       if (tier === 1 || (tier === 2 && REDACT_TIER_2)) {
 57 |         const { x, y, w, h } = region.bounding_box;
 58 | 
 59 |         let catW = 260;
 60 |         let catH = 24;
 61 | 
 62 |         if (w <= 80 && h <= 24) {
 63 |           catW = 80;
 64 |           catH = 24;
 65 |         } else if (w <= 160 && h <= 24) {
 66 |           catW = 160;
 67 |           catH = 24;
 68 |         } else {
 69 |           catW = 260;
 70 |           catH = 24;
 71 |         }
 72 | 
 73 |         const centerX = x + w / 2;
 74 |         const centerY = y + h / 2;
 75 |         const drawX = centerX - catW / 2;
 76 |         const drawY = centerY - catH / 2;
 77 | 
 78 |         if (ctx && typeof ctx.fillRect === 'function') {
 79 |           ctx.fillStyle = '#000000';
 80 |           ctx.fillRect(drawX, drawY, catW, catH);
 81 |         }
 82 |       }
 83 |     }
 84 |   }
 85 | 
 86 |   return outputCanvas;
 87 | }
