41 | function getAmountToken(elementClassification, piiMatches) {
42 |   let numberStr = null;
43 | 
44 |   if (Array.isArray(piiMatches)) {
45 |     for (const m of piiMatches) {
46 |       if (m && m.match) {
47 |         const numMatch = m.match.match(/\d+(?:\.\d+)?/);
48 |         if (numMatch) {
49 |           numberStr = numMatch[0];
50 |           break;
51 |         }
52 |       }
53 |     }
54 |   }
55 | 
56 |   if (!numberStr && elementClassification) {
57 |     const textToSearch = [
58 |       elementClassification.label_text,
59 |       elementClassification.value
60 |     ].filter(Boolean).join(' ');
61 | 
