 87 | export function classifySensitivity(elementClassification, piiMatches = [], rawValue = null, tokenVault = null) {
 88 |   const domType = (elementClassification && elementClassification.sensitivity_type && elementClassification.sensitivity_type !== 'UNKNOWN')
 89 |     ? elementClassification.sensitivity_type
 90 |     : null;
 91 | 
 92 |   const validPiiMatches = Array.isArray(piiMatches) ? piiMatches.filter(m => m && m.type) : [];
 93 | 
 94 |   let chosenType = null;
 95 | 
 96 |   if (validPiiMatches.length > 0) {
 97 |     // Pick highest sensitivity (lowest tier number) among PII matches
 98 |     let bestPiiType = validPiiMatches[0].type;
 99 |     let bestPiiTier = getTierNumber(bestPiiType);
100 | 
101 |     for (let i = 1; i < validPiiMatches.length; i++) {
102 |       const t = validPiiMatches[i].type;
103 |       const tier = getTierNumber(t);
104 |       if (tier < bestPiiTier) {
105 |         bestPiiType = t;
106 |         bestPiiTier = tier;
107 |       }
108 |     }
109 | 
110 |     if (!domType) {
111 |       chosenType = bestPiiType;
112 |     } else if (domType === bestPiiType) {
113 |       chosenType = domType;
114 |     } else {
115 |       const domTier = getTierNumber(domType);
116 | 
117 |       if (domTier < bestPiiTier) {
118 |         chosenType = domType;
119 |       } else if (bestPiiTier < domTier) {
120 |         chosenType = bestPiiType;
121 |       } else {
122 |         chosenType = bestPiiType;
123 |       }
124 | 
125 |       console.warn(
126 |         `Sensitivity type mismatch: DOM heuristic detected "${domType}" (Tier ${domTier}) but PII pattern detected "${bestPiiType}" (Tier ${bestPiiTier}). Defaulting to higher sensitivity tier type: "${chosenType}".`
127 |       );
128 |     }
129 |   } else if (domType) {
130 |     chosenType = domType;
131 |   }
132 | 
133 |   if (!chosenType || chosenType === 'UNKNOWN') {
134 |     return {
135 |       sensitivity_tier: 3,
136 |       sensitivity_type: 'UNKNOWN',
137 |       semantic_token: null
138 |     };
139 |   }
140 | 
141 |   const tier = getTierNumber(chosenType);
142 | 
143 |   let semantic_token = null;
144 | 
145 |   if (tier === 1 || tier === 2) {
146 |     if (tokenVault && typeof tokenVault.getOrCreateToken === 'function' && rawValue !== null && rawValue !== undefined && rawValue !== '') {
147 |       semantic_token = tokenVault.getOrCreateToken(rawValue, chosenType);
148 |     } else {
149 |       if (tier === 1) {
150 |         semantic_token = `[${chosenType}]`;
151 |       } else {
152 |         semantic_token = chosenType === 'AMOUNT'
153 |           ? getAmountToken(elementClassification, piiMatches)
154 |           : `[${chosenType}]`;
155 |       }
156 |     }
157 |   }
158 | 
159 |   return {
160 |     sensitivity_tier: tier,
161 |     sensitivity_type: chosenType,
162 |     semantic_token
163 |   };
164 | }

