 1 | import { createTokenVault } from './token-vault.js';
 2 | 
 3 | const sessionVaults = new Map(); // session_id -> { vault, createdAt, lastAccessedAt }
 4 | const MAX_SESSIONS_THRESHOLD = 20;
 5 | export const DEFAULT_SESSION_TTL_MS = 30 * 60 * 1000; // 30 minutes default TTL
 6 | 
 7 | /**
 8 |  * Gets an existing token vault instance for a session_id, or creates a new one.
 9 |  * Automatically checks for expired session vaults and invalidates them if TTL exceeded.
10 |  * @param {string} session_id - Unique identifier for the active task session.
11 |  * @param {number} [ttlMs=DEFAULT_SESSION_TTL_MS] - Optional custom TTL in milliseconds.
12 |  * @returns {object} Token vault instance.
13 |  */
14 | export function getVaultForSession(session_id, ttlMs = DEFAULT_SESSION_TTL_MS) {
15 |   if (!session_id || typeof session_id !== 'string') {
16 |     throw new Error('Invalid session_id provided to getVaultForSession');
17 |   }
18 | 
19 |   const now = Date.now();
20 | 
21 |   if (sessionVaults.has(session_id)) {
22 |     const record = sessionVaults.get(session_id);
23 |     if (now - record.lastAccessedAt > ttlMs) {
24 |       // Session has expired -> clean up
25 |       endSession(session_id);
26 |     } else {
27 |       record.lastAccessedAt = now;
28 |       return record.vault;
29 |     }
30 |   }
31 | 
32 |   if (sessionVaults.size >= MAX_SESSIONS_THRESHOLD) {
33 |     console.warn(
34 |       `[Privacy Warning] Active session vault count reached ${sessionVaults.size + 1} (> ${MAX_SESSIONS_THRESHOLD}). Potential session leak: ensure endSession() is called upon task completion/error.`
35 |     );
36 |   }
37 | 
38 |   const newVault = createTokenVault();
39 |   sessionVaults.set(session_id, {
40 |     vault: newVault,
41 |     createdAt: now,
42 |     lastAccessedAt: now
43 |   });
44 |   return newVault;
45 | }
46 | 
47 | /**
48 |  * Clears and removes the token vault instance for a completed, terminated, or expired session.
49 |  * @param {string} session_id - Unique identifier for the task session to end.
50 |  */
51 | export function endSession(session_id) {
52 |   if (!session_id || typeof session_id !== 'string') return;
53 | 
54 |   const record = sessionVaults.get(session_id);
55 |   if (record) {
56 |     if (record.vault && typeof record.vault.clear === 'function') {
57 |       record.vault.clear();
58 |     }
59 |     sessionVaults.delete(session_id);
60 |   }
61 | }
62 | 
63 | /**
64 |  * Sweeps and prunes all expired session vaults exceeding TTL.
65 |  * @param {number} [ttlMs=DEFAULT_SESSION_TTL_MS]
66 |  * @returns {number} Count of expired sessions cleaned.
67 |  */
68 | export function cleanExpiredSessions(ttlMs = DEFAULT_SESSION_TTL_MS) {
69 |   const now = Date.now();
70 |   let cleanedCount = 0;
71 | 
72 |   for (const [id, record] of sessionVaults.entries()) {
73 |     if (now - record.lastAccessedAt > ttlMs) {
74 |       endSession(id);
75 |       cleanedCount++;
76 |     }
77 |   }
78 | 
79 |   return cleanedCount;
80 | }
81 | 
82 | /**
83 |  * Returns the current count of active session vaults.
84 |  * @returns {number} Count of active task sessions.
85 |  */
86 | export function getActiveSessionCount() {
87 |   return sessionVaults.size;
88 | }

