 1 | /**
 2 |  * Creates an in-memory token vault for session-scoped mapping between sensitive values and tokens.
 3 |  * @returns {{
 4 |  *   getOrCreateToken: (rawValue: string, sensitivityType: string) => string,
 5 |  *   resolveToken: (token: string) => string | null,
 6 |  *   hasToken: (token: string) => boolean,
 7 |  *   clear: () => void,
 8 |  *   getStats: () => { totalTokens: number, byType: Record<string, number> }
 9 |  * }}
10 |  */
11 | export function createTokenVault() {
12 |   const forwardMap = new Map(); // rawValue -> token
13 |   const reverseMap = new Map(); // token -> rawValue
14 |   const typeCounters = new Map(); // sensitivityType -> current counter integer
15 | 
16 |   return {
17 |     /**
18 |      * Gets existing token for rawValue or creates a new indexed token [TYPE_N].
19 |      * @param {string} rawValue
20 |      * @param {string} sensitivityType
21 |      * @returns {string}
22 |      */
23 |     getOrCreateToken(rawValue, sensitivityType) {
24 |       if (typeof rawValue !== 'string' || !rawValue) {
25 |         return '';
26 |       }
27 | 
28 |       const typeKey = (sensitivityType || 'UNKNOWN').toUpperCase();
29 | 
30 |       if (forwardMap.has(rawValue)) {
31 |         return forwardMap.get(rawValue);
32 |       }
33 | 
34 |       const currentCount = (typeCounters.get(typeKey) || 0) + 1;
35 |       typeCounters.set(typeKey, currentCount);
36 | 
37 |       const token = `[${typeKey}_${currentCount}]`;
38 |       forwardMap.set(rawValue, token);
39 |       reverseMap.set(token, rawValue);
40 | 
41 |       return token;
42 |     },
43 | 
44 |     /**
45 |      * Resolves token back to raw value.
46 |      * @param {string} token
47 |      * @returns {string | null}
48 |      */
49 |     resolveToken(token) {
50 |       if (typeof token !== 'string' || !token) {
51 |         return null;
52 |       }
53 |       return reverseMap.get(token) || null;
54 |     },
55 | 
56 |     /**
57 |      * Checks if token exists in the vault.
58 |      * @param {string} token
59 |      * @returns {boolean}
60 |      */
61 |     hasToken(token) {
62 |       if (typeof token !== 'string' || !token) {
63 |         return false;
64 |       }
65 |       return reverseMap.has(token);
66 |     },
67 | 
68 |     /**
69 |      * Clears all mapped tokens and resets state for session teardown.
70 |      */
71 |     clear() {
72 |       forwardMap.clear();
73 |       reverseMap.clear();
74 |       typeCounters.clear();
75 |     },
76 | 
77 |     /**
78 |      * Returns count statistics without exposing raw values or tokens.
79 |      * @returns {{ totalTokens: number, byType: Record<string, number> }}
80 |      */
81 |     getStats() {
82 |       const byType = {};
83 | 
84 |       for (const [token] of reverseMap.entries()) {
85 |         const match = token.match(/^\[([A-Z_]+)_\d+\]$/);
86 |         const type = match ? match[1] : 'UNKNOWN';
87 |         byType[type] = (byType[type] || 0) + 1;
88 |       }
89 | 
90 |       return {
91 |         totalTokens: reverseMap.size,
92 |         byType
93 |       };
94 |     }
95 |   };
96 | }
